```c
#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    long long *prev = (long long *)malloc(C * sizeof(long long));
    long long *curr = (long long *)malloc(C * sizeof(long long));
    int m = C - 1;
    int *heights = (int *)calloc(m, sizeof(int));
    int *stack = (int *)malloc((m + 1) * sizeof(int));

    long long ans = (L > C) ? L : C;

    for (int j = 0; j < C; j++) {
        scanf("%lld", &prev[j]);
    }

    for (int i = 1; i < L; i++) {
        for (int j = 0; j < C; j++) {
            scanf("%lld", &curr[j]);
        }

        for (int j = 0; j < m; j++) {
            if (prev[j] + curr[j + 1] <= prev[j + 1] + curr[j]) {
                heights[j]++;
            } else {
                heights[j] = 0;
            }
        }

        int top = 0;
        for (int j = 0; j <= m; j++) {
            int cur = (j == m) ? 0 : heights[j];
            while (top > 0 && heights[stack[top - 1]] > cur) {
                int h = heights[stack[--top]];
                int left = (top == 0) ? -1 : stack[top - 1];
                int width = j - left - 1;
                if (h > 0) {
                    long long area = (long long)(h + 1) * (width + 1);
                    if (area > ans) ans = area;
                }
            }
            if (j < m) {
                stack[top++] = j;
            }
        }

        long long *tmp = prev;
        prev = curr;
        curr = tmp;
    }

    printf("%lld\n", ans);

    free(prev);
    free(curr);
    free(heights);
    free(stack);
    return 0;
}
